    public string CurrentLanguage { get; private set; } = "en";
    public event Action? Changed;

    public void SetLanguage(string language)
    {
        if (!Texts.ContainsKey(language) || CurrentLanguage.Equals(language, StringComparison.OrdinalIgnoreCase))
            return;

        CurrentLanguage = language;
        Changed?.Invoke();
    }

    public string Text(string key) =>
        Texts[CurrentLanguage].TryGetValue(key, out var value)
            ? value
            : Texts["en"].GetValueOrDefault(key, key);

    public static bool IsSupported(string? language) =>
        language is not null && Texts.ContainsKey(language);
}







